function largestNearlyAbsent(nums: number[], k: number): number {
  const n = nums.length;
  if (k === n) return Math.max(...nums);
  const count = new Map<number, number>();
  for (const v of nums) count.set(v, (count.get(v) ?? 0) + 1);
  if (k === 1) {
    let best = -1;
    for (const [v, c] of count) if (c === 1) best = Math.max(best, v);
    return best;
  }
  const first = nums[0], last = nums[n - 1];
  let best = -1;
  if (count.get(first) === 1) best = Math.max(best, first);
  if (count.get(last) === 1) best = Math.max(best, last);
  return best;
}

